"""Random strings built from runs of 1 to 14 repeated letters."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    out = []
    for _ in range(rng.randint(0, 6)):
        out.append(rng.choice("abxyz.- ") * rng.randint(1, 14))
    return {"name": "runs #%d" % index, "stdin": "".join(out) + "\n"}
